<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useAuth} from '../stores/auth';
import {useRoute,useRouter} from 'vue-router';
import {managementRequest} from '../api/management';
import CockpitIcon from '../components/CockpitIcon.vue';
import {cycleStatus,dateTime,filterCycles,validateCycleForm,type ManagedCycle,type CycleDetail} from '../lib/cycle-management';
import {percent} from '../lib/cockpit';
import {monthlyPath} from '../lib/monthly-navigation';
const route=useRoute(),router=useRouter(),auth=useAuth();
const rows=ref<ManagedCycle[]>([]),selectedId=ref(''),canCreate=ref(false),loading=ref(true),error=ref(''),success=ref('');
const archived=ref(false),search=ref(''),status=ref(''),year=ref(''),page=ref(1),pageSize=ref(10);
const current=computed(()=>rows.value.find(c=>c.id===selectedId.value));
const years=computed(()=>[...new Set(rows.value.map(c=>c.month.slice(0,4)))].sort().reverse());
const statuses=computed(()=>[...new Set(rows.value.filter(c=>c.status!=='ARCHIVED').map(cycleStatus))]);
const filtered=computed(()=>filterCycles(rows.value,search.value,status.value,year.value,archived.value));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value)));
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const stats=computed(()=>current.value?[{name:'参评人数',icon:'people',value:current.value.participants,note:'周期有效参评快照',tone:'neutral'},
 {name:'材料提交',icon:'document',value:current.value.materials,expected:current.value.participants,rate:current.value.materialRate,tone:'blue'},
 {name:'自评完成',icon:'edit',value:current.value.self_submitted,expected:current.value.participants,rate:current.value.selfRate,tone:'teal'},
 {name:'他评完成',icon:'people',value:current.value.peer_submitted,expected:current.value.peer_expected,rate:current.value.peerRate,tone:'purple'}]:[]);
type ProgressRow={user_id:string;display_name:string;department_id:string|null;department_name:string|null;eligibility:string;materials:number;self_submitted:number;peer_expected:number;peer_submitted:number};
const progressDialog=ref<HTMLDialogElement>(),progressRows=ref<ProgressRow[]>([]),progressKind=ref(''),progressLoading=ref(false),progressError=ref(''),progressSearch=ref(''),progressDepartment=ref('');
const progressDepartments=computed(()=>[...new Set(progressRows.value.map(r=>r.department_name||'未分配'))].sort());
const progressFiltered=computed(()=>progressRows.value.filter(r=>(!progressDepartment.value||(r.department_name||'未分配')===progressDepartment.value)&&r.display_name.includes(progressSearch.value.trim())));
const progressGroups=computed(()=>{const groups=new Map<string,ProgressRow[]>();for(const r of progressFiltered.value){const key=r.department_name||'未分配';groups.set(key,[...(groups.get(key)||[]),r]);}return [...groups].map(([name,items])=>({name,items}));});
type TaskRow={id:string;reviewer_id:string;target_id:string;reviewer_name:string;target_name:string;reviewer_department:string|null;target_department:string|null;completed:boolean};
type MaterialRow={id:string;name:string;versions:Array<{id:string;fileName:string}>};
const extraDialog=ref<HTMLDialogElement>(),extraTitle=ref(''),extraLoading=ref(false),extraError=ref(''),materialRows=ref<MaterialRow[]>([]),taskRows=ref<TaskRow[]>([]),extraMember=ref<ProgressRow|null>(null),taskDirection=ref<'outgoing'|'incoming'>('outgoing');
const memberTasks=computed(()=>taskRows.value.filter(t=>taskDirection.value==='outgoing'?t.reviewer_id===extraMember.value?.user_id:t.target_id===extraMember.value?.user_id));
async function openMemberDetails(member:ProgressRow){extraMember.value=member;extraTitle.value=member.display_name+(progressKind.value==='材料提交'?' · 材料':' · 他评任务');extraError.value='';materialRows.value=[];taskRows.value=[];taskDirection.value='outgoing';extraLoading.value=true;await nextTick();extraDialog.value?.showModal();try{const path=progressKind.value==='材料提交'?`cycles/${selectedId.value}/participants/${member.user_id}/materials`:`management/cycle-progress-tasks?cycleId=${encodeURIComponent(selectedId.value)}`;const response=await fetch('/api/v1/'+path,{credentials:'include'});const json=await response.json();if(!response.ok)throw new Error(response.status===403?'当前账号没有查看该详情的权限。':'详情加载失败，请稍后重试。');if(progressKind.value==='材料提交')materialRows.value=json.data;else taskRows.value=json.data;}catch(e){extraError.value=errorText(e);}finally{extraLoading.value=false;}}
let progressRequest:AbortController|undefined;
async function openProgress(kind:string){if(!selectedId.value)return;progressRequest?.abort();const req=new AbortController();progressRequest=req;progressKind.value=kind;progressRows.value=[];progressSearch.value='';progressDepartment.value='';progressError.value='';progressLoading.value=true;await nextTick();progressDialog.value?.showModal();try{const response=await fetch('/api/v1/management/cycle-progress?'+new URLSearchParams({cycleId:selectedId.value}),{credentials:'include',signal:req.signal});const json=await response.json();if(!response.ok)throw new Error(response.status===403?'当前账号无权查看该周期的进度详情。':'进度详情加载失败，请重试。');if(!req.signal.aborted)progressRows.value=json.data;}catch(e){if(!req.signal.aborted)progressError.value=errorText(e);}finally{if(progressRequest===req)progressLoading.value=false;}}
const dialog=ref<HTMLDialogElement>(),createDialog=ref<HTMLDialogElement>(),actionDialog=ref<HTMLDialogElement>(),publishDialog=ref<HTMLDialogElement>();
const publishPreview=ref<{id:string;feasible:boolean;diagnostics:string[];edge_count:number;shortfalls?:Array<{targetId:string;targetName?:string;department_name?:string|null;indegree:number;minIndegree:number;missing:number;reason:string}>}|null>(null),publishError=ref('');
/** 预检缺口的可能原因说明；只解释机制，不承诺具体成因。 */
const shortfallReasons:Record<string,string>={INSUFFICIENT_CANDIDATES:'本部门可参与评价的人不足，且跨部门候选已被占用。',REVIEWER_CAPACITY:'可评价人员的出度已达上限，组织整体评价容量不足。',SINGLE_MEMBER_DEPARTMENT:'所在部门只有本人，需要跨部门补足。',OTHER:'存在重复关系、历史回避或其他约束，需人工指定补足。'};
const shortfallHint=computed(()=>publishPreview.value?.shortfalls?.length?'这些成员目前能获得的他评不足，不能靠强行通过预检解决：可先在评价分配中人工指定关系，或调整参评名单后重新预检。':'');
function describeDiagnostic(value:string){return value.replace(/参与者 ([0-9a-f-]{36})\((HEAD|MEMBER)\) 入度为 (\d+)，低于 (\d+)/gi,(_,id,_role,actual,required)=>{const p=detail.value?.participants.find(p=>p.user_id===id);return `${p?.display_name??'参评成员'}（${p?.department_name??'部门未知'}）目前获得 ${actual} 份评价，需要至少 ${required} 份；请检查参评名单及分配规则。`;});}
const detail=ref<CycleDetail|null>(null),detailLoading=ref(false),detailError=ref(''),panel=ref('config'),editing=ref(false),busy=ref(false);
const allocationState=ref<'checking'|'ready'|'missing'|'unavailable'>('checking');
const rules=ref<Array<{id:string;version:number;status:string}>>([]),formError=ref(''),creating=ref(false),rulesLoading=ref(false);
const emptyForm=()=>({title:'',month:'',open_at:'',self_close_at:'',close_at:'',publish_at:'',ruleset_id:''});
const form=ref(emptyForm()),editForm=ref(emptyForm()),action=ref(''),actionReason=ref(''),actionError=ref('');
let listController:AbortController|undefined,detailController:AbortController|undefined;
const localTime=(v?:string|null)=>{if(!v)return '';const d=new Date(v);return Number.isFinite(d.getTime())?new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16):'';};
const errorText=(e:unknown)=>{const text=e instanceof Error?e.message:String(e);return ({AUTH_REQUIRED:'登录状态已失效，请刷新页面重新登录。',NOT_DRAFT:'当前周期不是草稿，配置不可修改。',STATE_CONFLICT:'周期已被更新，请刷新后重试。',DRAFT_HAS_BUSINESS_DATA:'已有正式关联业务数据，不能删除。',PUBLISHED_CANNOT_CANCEL:'已有正式发布结果，不能撤销整个周期。',FORBIDDEN:'当前账号没有执行此操作的权限。',SCHEDULE_INVALID:'评价时间顺序无效，请重新检查。',RULESET_NOT_FROZEN:'所选规则未冻结或不在授权组织内。',CYCLE_STATUS_INVALID:'周期状态已变化，请刷新后重试。',CYCLE_ACTIVE_EXISTS:'已有进行中的月评周期，同一时间只能开启一期。请先完成或撤销当前周期，再发起新一期。',CYCLE_CREATE_CONFLICT:'周期创建冲突，请刷新页面后重试。',NOT_CANCELLED:'只有已撤销的周期可以重启为草稿。',RESOURCE_NOT_FOUND:'周期不存在或不在授权范围内。'} as Record<string,string>)[text]??text;};
const chip=(s:string)=>({REVIEWING:'blue',PAUSED:'amber',PENDING_OPEN:'amber',CALIBRATING:'amber',PARTIALLY_PUBLISHED:'purple',PUBLISHED:'green',ARCHIVED:'gray',CANCELLED:'red',DRAFT:'gray'}[s]??'gray');
watch([search,status,year,archived,pageSize],()=>page.value=1);
watch(pages,n=>page.value=Math.min(n,page.value));
watch(archived,()=>{status.value='';});
async function load(){
 listController?.abort();const req=new AbortController();listController=req;loading.value=true;error.value='';
 try{const response=await fetch('/api/v1/management/dashboard',{credentials:'include',signal:req.signal});const json=await response.json();if(!response.ok)throw new Error(json.code??'周期列表加载失败');
  if(listController!==req)return;rows.value=json.data;canCreate.value=json.permissions?.canCreate===true;
  const preferred=String(route.params.cycleId??route.query.cycleId??selectedId.value);
  selectedId.value=(rows.value.find(c=>c.id===preferred)??rows.value.find(c=>['REVIEWING','CALIBRATING','PARTIALLY_PUBLISHED'].includes(c.status))??rows.value.find(c=>c.status==='PENDING_OPEN')??rows.value[0])?.id??'';
 }catch(e){if(!req.signal.aborted)error.value=errorText(e);}finally{if(listController===req)loading.value=false;}
}
async function loadDetail(){
 const id=String(route.params.cycleId??'');if(!id){detailController?.abort();dialog.value?.close();detail.value=null;return;}
 detailController?.abort();const req=new AbortController();detailController=req;detailLoading.value=true;detail.value=null;detailError.value='';allocationState.value='checking';editing.value=false;
 panel.value=['participants','history'].includes(String(route.query.panel))?String(route.query.panel):'config';
 await nextTick();if(!dialog.value?.open)dialog.value?.showModal();
 try{const response=await fetch('/api/v1/management/cycle-detail?'+new URLSearchParams({cycleId:id}),{credentials:'include',signal:req.signal});const json=await response.json();if(!response.ok)throw new Error(json.code??'周期详情加载失败');if(req.signal.aborted)return;detail.value=json.data;selectedId.value=id;
  if(['DRAFT','PENDING_OPEN'].includes(json.data.cycle.status)){
   if(!auth.hasCapability('assignment.manage'))allocationState.value='unavailable';
   else try{const saved=await managementRequest<{id:string}|null>(`cycles/${id}/assignment/confirmed-preview`);if(!req.signal.aborted)allocationState.value=saved?'ready':'missing';}catch{if(!req.signal.aborted)allocationState.value='unavailable';}
  }else allocationState.value='unavailable';}
 catch(e){if(!req.signal.aborted)detailError.value=errorText(e);}finally{if(detailController===req)detailLoading.value=false;}
}
function openDetail(c:ManagedCycle,view='config'){selectedId.value=c.id;return router.push({path:monthlyPath('cycles',c.id),query:{panel:view}});}
function closeDetail(){if(busy.value)return;dialog.value?.close();return router.push({path:monthlyPath('cycles'),query:{cycleId:selectedId.value}});}
watch(()=>[route.params.cycleId,route.query.panel],()=>void loadDetail());
async function remindMe(){const cycle=detail.value?.cycle;if(!cycle)return;busy.value=true;success.value='';try{const r=await managementRequest<{queued:number;text?:string;reason?:string;hint?:string}>(`cycles/${cycle.id}/remind-me`,{});success.value=r.queued?`催办提醒已排队，约 30 秒内推送到你的飞书：${r.text??''}`:(r.hint??'当前阶段没有需要发送的提醒。');}catch(e){success.value=errorText(e);}finally{busy.value=false;}}
async function openCreate(){formError.value='';success.value='';form.value=emptyForm();await nextTick();createDialog.value?.showModal();rulesLoading.value=true;try{rules.value=await managementRequest('rulesets');form.value.ruleset_id=rules.value.find(r=>r.status==='FROZEN')?.id??'';}catch(e){formError.value=errorText(e);}finally{rulesLoading.value=false;}}
function setMonth(value:string){form.value.month=value;if(!value)return;form.value.title=`${value} 月度环评`;const [y,m]=value.split('-').map(Number),last=new Date(y,m,0).getDate();form.value.open_at=value+'-01T09:00';form.value.self_close_at=`${value}-${String(Math.max(1,last-3)).padStart(2,'0')}T18:00`;form.value.close_at=`${value}-${String(last-1).padStart(2,'0')}T18:00`;form.value.publish_at=`${value}-${last}T18:00`;}
async function create(){if(creating.value)return;formError.value=validateCycleForm(form.value,rows.value);if(formError.value)return;creating.value=true;
 try{const c=await managementRequest<{id:string}>('cycles',{...form.value,title:form.value.title.trim(),open_at:new Date(form.value.open_at).toISOString(),self_close_at:form.value.self_close_at?new Date(form.value.self_close_at).toISOString():null,close_at:new Date(form.value.close_at).toISOString(),publish_at:new Date(form.value.publish_at).toISOString()});createDialog.value?.close();selectedId.value=c.id;archived.value=false;search.value='';year.value='';status.value='';success.value='月评周期草稿已创建，参评快照已生成。';await router.push({path:monthlyPath('relations'),query:{cycleId:c.id,created:'1'}});}
 catch(e){formError.value=errorText(e);}finally{creating.value=false;}}
function startEdit(){const c=detail.value?.cycle;if(!c)return;editForm.value={title:c.title,month:c.month.slice(0,7),ruleset_id:c.ruleset_id,open_at:localTime(c.open_at),self_close_at:localTime(c.self_close_at),close_at:localTime(c.close_at),publish_at:localTime(c.publish_at)};editing.value=true;detailError.value='';}
async function saveEdit(){if(!detail.value||busy.value)return;const invalid=validateCycleForm(editForm.value,rows.value,detail.value.cycle.id);if(invalid){detailError.value=invalid;return;}busy.value=true;
 try{await managementRequest(`cycles/${detail.value.cycle.id}`,{...editForm.value,row_version:detail.value.cycle.row_version,open_at:new Date(editForm.value.open_at).toISOString(),self_close_at:editForm.value.self_close_at?new Date(editForm.value.self_close_at).toISOString():null,close_at:new Date(editForm.value.close_at).toISOString(),publish_at:new Date(editForm.value.publish_at).toISOString()},'PUT');success.value='周期配置已保存。';await Promise.all([load(),loadDetail()]);}catch(e){detailError.value=errorText(e);}finally{busy.value=false;}}
async function preparePublish(){if(!detail.value||busy.value)return;publishError.value='';publishPreview.value=null;publishDialog.value?.showModal();
 if(new Date(detail.value.cycle.close_at).getTime()<=Date.now()){publishError.value='评价截止时间已过，请先修改周期时间。';return;}
 busy.value=true;try{publishPreview.value=await managementRequest(`cycles/${detail.value.cycle.id}/assignment/confirmed-preview`);if(!publishPreview.value){allocationState.value='missing';publishError.value='分配方案尚未保存或已失效，请前往评价分配重新预览并保存。';}}catch(e){publishError.value=({NO_PARTICIPANTS:'本周期没有有效参评成员，请先检查参评名单。',FORBIDDEN:'当前账号没有本周期的分配检查权限。',STATE_CONFLICT:'周期状态已变化，请刷新后重试。'} as Record<string,string>)[e instanceof Error?e.message:'']??'分配状态暂时无法检查，请稍后重试。';}finally{busy.value=false;}}
async function publishCycle(){if(!detail.value||!publishPreview.value?.feasible||busy.value)return;busy.value=true;publishError.value='';const cycle=detail.value.cycle;
 try{if(new Date(cycle.close_at).getTime()<=Date.now())throw new Error('评价截止时间已过，请先修改周期时间。');if(cycle.status==='DRAFT'){await managementRequest(`cycles/${cycle.id}/submit`,{});cycle.status='PENDING_OPEN';}
 const result=await managementRequest<{status:string}>(`cycles/${cycle.id}/open`,{run_id:publishPreview.value.id});publishDialog.value?.close();success.value=result.status==='REVIEWING'?'月评已发起，个人端现在可以上传材料。':'月评已确认，将在评价开始时间进入评价中，届时个人端可以上传材料。';await Promise.all([load(),loadDetail()]);
 }catch(e){const code=e instanceof Error?e.message:String(e);publishError.value=({OPEN_WINDOW_CLOSED:'评价截止时间已过，无法发起周期。',OPEN_PREREQUISITE_MISSING:'尚未满足开期所需的系统配置，请检查评价规则和评价分配。',RUN_INPUT_CHANGED:'参评名单或评价关系已变化，请关闭窗口后重新预检。',RUN_NOT_FEASIBLE:'预检结果已失效，请关闭窗口后重新预检。',ASSIGNMENT_LOCKED:'周期状态已变化，请刷新后重试。'} as Record<string,string>)[code]??errorText(e);publishPreview.value=null;await load();}finally{busy.value=false;}}
const archiveCheck=ref<{eligible:boolean;checks:Array<{key:string;ok:boolean;message:string;path:string}>}|null>(null);
async function confirmAction(kind:string){action.value=kind;actionReason.value='';actionError.value='';archiveCheck.value=null;actionDialog.value?.showModal();if(kind==='archive'&&detail.value){busy.value=true;try{archiveCheck.value=await managementRequest(`cycles/${detail.value.cycle.id}/archive-preflight`);}catch{actionError.value='归档条件检查失败，请检查权限或稍后重试。';}finally{busy.value=false;}}}
async function execute(){if(!detail.value||busy.value)return;if(['cancel','pause','resume'].includes(action.value)&&!actionReason.value.trim()){actionError.value='请填写操作原因。';return;}busy.value=true;actionError.value='';const id=detail.value.cycle.id;
 try{const type=action.value;if(type==='delete')await managementRequest(`cycles/${id}`,undefined,'DELETE');else await managementRequest(`cycles/${id}/${type==='refresh'?'participants/refresh':type}`,['cancel','pause','resume'].includes(type)?{reason:actionReason.value.trim()}:{});
  actionDialog.value?.close();success.value=({delete:(detail.value?.cycle.status==='CANCELLED'?'已撤销周期及其业务数据已删除。':'草稿周期已删除。'),restore:'已重启为草稿：评价、材料与结果数据已清空，参评名单保留，可重新配置后发起。',archive:'周期已归档，历史快照保留。',refresh:'参评快照已刷新；评价关系仍需单独确认。',cancel:'周期已撤销，关联历史已保留。',pause:'月评已暂停，截止时间保持不变。',resume:'月评已恢复，仍按原截止时间执行。'} as Record<string,string>)[type];await load();if(type==='delete'){dialog.value?.close();await router.push(monthlyPath('cycles'));}else await loadDetail();
 }catch(e){actionError.value=action.value==='archive'?'归档未完成，周期状态或检查条件可能已变化，请关闭后重新检查。':errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{await load();await loadDetail();});
onBeforeUnmount(()=>{listController?.abort();detailController?.abort();dialog.value?.close();createDialog.value?.close();actionDialog.value?.close();publishDialog.value?.close();});
</script>
<template>
 <div class="cycle-management">
  <p v-if="success" class="success" role="status">{{success}} <RouterLink v-if="success.includes('下一步')" :to="{path:monthlyPath('relations'),query:{cycleId:selectedId}}">前往评价分配 →</RouterLink></p>
  <div v-if="error" class="error" role="alert">{{error}} <button class="btn" @click="load">重试</button></div>
  <div v-if="loading&&!rows.length" class="surface empty" role="status">正在加载周期与有效统计…</div>
  <template v-if="current">
   <section class="surface current-cycle" aria-label="当前周期概览"><div class="current-title"><span class="icon blue"><CockpitIcon name="cycle"/></span><div><h2>当前周期</h2><div class="cycle-title"><strong>{{current.title}}</strong><span class="state" :class="chip(current.status)">{{cycleStatus(current)}}</span></div></div></div><div class="schedule"><small>评价时间</small><span>{{dateTime(current.open_at)}} — {{dateTime(current.close_at)}}</span></div><div class="publish-date"><small>结果发布时间</small><span>{{dateTime(current.publish_at)}}</span></div><div class="overview-actions"><button class="btn" @click="openDetail(current,'participants')">查看参评名单（{{current.participants}}）</button><button class="btn btn-primary" @click="openDetail(current)">{{current.status==='ARCHIVED'?'查看周期配置':'进入周期配置'}}</button></div></section>
   <section class="surface statistics"><div class="statistics-head"><h2>周期统计</h2><select v-model="selectedId" aria-label="统计周期"><option v-for="c in rows" :key="c.id" :value="c.id">{{c.title}} · {{c.month}}</option></select></div><div class="stats"><article v-for="s in stats" :key="s.name" :class="s.tone" role="button" tabindex="0" :aria-label="'查看'+s.name+'详情'" @click="openProgress(s.name)" @keydown.enter.prevent="openProgress(s.name)" @keydown.space.prevent="openProgress(s.name)"><span class="icon"><CockpitIcon :name="s.icon"/></span><div><h3>{{s.name}}</h3><div class="stat-value"><strong>{{s.value}}</strong><span v-if="s.expected!==undefined"> / {{s.expected}} <span>（{{percent(s.rate)}}）</span></span></div><progress v-if="s.rate!=null" :value="s.rate" max="1" :aria-label="s.name+'完成率'"/><small v-if="s.note">{{s.note}}</small></div></article></div></section>
  </template>
  <section class="surface cycle-list" :aria-busy="loading"><div class="list-tabs" role="tablist" aria-label="周期记录类型"><button role="tab" :aria-selected="!archived" :class="{active:!archived}" @click="archived=false">周期列表</button><button role="tab" :aria-selected="archived" :class="{active:archived}" @click="archived=true">归档记录</button></div>
   <div class="filters"><label class="search"><span class="sr-only">搜索周期名称或月份</span><input v-model="search" :placeholder="archived?'搜索历史周期名称或月份':'搜索周期名称或月份'"/></label><label v-if="!archived"><span class="sr-only">周期状态</span><select v-model="status" aria-label="周期状态"><option value="">全部状态</option><option v-for="s in statuses" :key="s" :value="s">{{s}}</option></select></label><label><span class="sr-only">年份</span><select v-model="year" aria-label="年份"><option value="">全部年份</option><option v-for="y in years" :key="y" :value="y">{{y}}年</option></select></label><button v-if="canCreate&&!archived" class="btn btn-primary create-button" @click="openCreate">＋ 创建月评周期</button></div>
   <div class="table-wrap"><table><thead><tr><th>周期名称</th><th>评价月份</th><th>评价时间</th><th>结果发布时间</th><th>参评人数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in visible" :key="c.id"><td><button class="name-link" @click="selectedId=c.id">{{c.title}}</button></td><td>{{c.month}}</td><td class="time-cell">{{dateTime(c.open_at)}}<span>至 {{dateTime(c.close_at)}}</span><span v-if="c.self_close_at">自评截止 {{dateTime(c.self_close_at)}}</span></td><td>{{dateTime(c.publish_at)}}</td><td>{{c.participants}}</td><td><span class="state" :class="chip(c.status)">{{cycleStatus(c)}}</span></td><td class="row-actions"><button class="text-button" @click="openDetail(c)">{{c.can_manage&&['DRAFT','PENDING_OPEN','REVIEWING','CALIBRATING'].includes(c.status)?'管理':'查看'}}</button><details><summary aria-label="更多操作">···</summary><div class="row-menu"><button @click="openDetail(c,'participants')">查看参评名单</button><button @click="openDetail(c,'history')">查看阶段记录</button><RouterLink v-if="auth.hasCapability('result.read_published')&&['PUBLISHED','ARCHIVED','PARTIALLY_PUBLISHED'].includes(c.status)" :to="{path:'/management/archives',query:{tab:'scores',cycleId:c.id}}">查看已发布结果</RouterLink></div></details></td></tr></tbody></table></div>
   <div v-if="!visible.length&&!loading" class="empty">{{archived?'暂无符合条件的归档记录':'暂无符合条件的周期'}}<p v-if="!rows.length">创建周期后，系统按有效组织名单生成独立参评快照。</p></div><div class="pagination"><span>共 {{filtered.length}} 条</span><div><button class="btn" :disabled="page<=1" aria-label="上一页" @click="page--">‹</button><span class="page-number">{{page}}</span><button class="btn" :disabled="page>=pages" aria-label="下一页" @click="page++">›</button><select v-model="pageSize" aria-label="每页条数"><option :value="10">10条/页</option><option :value="20">20条/页</option><option :value="50">50条/页</option></select></div></div>
  </section>
  <dialog ref="createDialog" class="cycle-dialog" aria-labelledby="create-cycle-title" @cancel="creating&&$event.preventDefault()"><form @submit.prevent="create"><div class="dialog-head"><h2 id="create-cycle-title">创建月评周期</h2><button type="button" class="close" :disabled="creating" aria-label="关闭创建表单" @click="createDialog?.close()">×</button></div><p class="hint">创建周期会保存独立参评快照，评价关系在「评价分配」中单独配置。</p><div class="form-grid"><label>周期名称 <em>*</em><input v-model="form.title" maxlength="100" required placeholder="例如：2026-11 月度环评"/></label><label>评价月份 <em>*</em><input type="month" :value="form.month" required @input="setMonth(($event.target as HTMLInputElement).value)"/></label><label>评价开始时间 <em>*</em><input v-model="form.open_at" type="datetime-local" required/></label><label>自评截止时间 <em>*</em><input v-model="form.self_close_at" type="datetime-local" required/></label><label>他评截止时间 <em>*</em><input v-model="form.close_at" type="datetime-local" required/></label><label>结果发布时间 <em>*</em><input v-model="form.publish_at" type="datetime-local" required/></label><label>评分规则 <em>*</em><select v-model="form.ruleset_id" required :disabled="rulesLoading"><option value="" disabled>选择已冻结规则</option><option v-for="r in rules.filter(r=>r.status==='FROZEN')" :key="r.id" :value="r.id">评分规则 V{{r.version}} · 已冻结</option></select></label></div><div class="snapshot-note"><b>时间窗口说明</b><p>评价开始 → <b>自评截止</b>：成员完成自评并上传材料，此阶段互评不开放；自评截止 → 他评截止：才开放同行/上级评价。这样能保证他评看到的是成员已定稿的材料。</p></div><div class="snapshot-note"><b>参评范围及名单生成方式</b><p>按当前有效组织成员和任命自动生成本期快照，排除系统定义的不参评人员。创建后可查看名单；草稿阶段可在人员调整后刷新。</p></div><p v-if="!rulesLoading&&!rules.some(r=>r.status==='FROZEN')" class="hint">暂无可用的已冻结规则，请先在评价规则中完成冻结。</p><p v-if="formError" class="error" role="alert">{{formError}}</p><div class="dialog-footer"><button type="button" class="btn" :disabled="creating" @click="createDialog?.close()">取消</button><button class="btn btn-primary" :disabled="creating||rulesLoading">{{creating?'正在创建…':'创建周期'}}</button></div></form></dialog>
  <dialog ref="dialog" class="cycle-dialog detail-dialog" aria-labelledby="cycle-detail-title" @cancel.prevent="closeDetail"><div class="dialog-head"><h2 id="cycle-detail-title">{{detail?.cycle.title??'周期详情'}}</h2><button class="close" :disabled="busy" aria-label="关闭周期详情" @click="closeDetail">×</button></div><p v-if="detailLoading" role="status" class="empty">正在加载周期详情…</p><div v-if="detailError" class="error" role="alert">{{detailError}}</div><template v-if="detail"><p class="hint"><span class="state" :class="chip(detail.cycle.status)">{{cycleStatus(rows.find(c=>c.id===detail?.cycle.id)??detail.cycle)}}</span>　{{detail.cycle.month}} · {{detail.cycle.status==='ARCHIVED'?'归档周期仅供查看':'按当前周期阶段限制操作'}}</p><nav class="detail-tabs" aria-label="周期详情内容"><button :class="{active:panel==='config'}" @click="panel='config'">周期配置</button><button :class="{active:panel==='participants'}" @click="panel='participants'">参评名单</button><button :class="{active:panel==='history'}" @click="panel='history'">阶段记录</button></nav>
   <template v-if="panel==='config'"><form v-if="editing" @submit.prevent="saveEdit"><div class="form-grid"><label>周期名称<input v-model="editForm.title" maxlength="100" required/></label><label>评价月份<input v-model="editForm.month" type="month" required/></label><label>评价开始时间<input v-model="editForm.open_at" type="datetime-local" required/></label><label>自评截止时间（含材料上传）<input v-model="editForm.self_close_at" type="datetime-local"/></label><label>他评截止时间<input v-model="editForm.close_at" type="datetime-local" required/></label><label>结果发布时间<input v-model="editForm.publish_at" type="datetime-local" required/></label></div><p class="hint">评分规则沿用创建时的冻结版本；保存时携带版本号检查并发修改。</p><div class="dialog-footer"><button type="button" class="btn" :disabled="busy" @click="editing=false">取消编辑</button><button class="btn btn-primary" :disabled="busy">{{busy?'保存中…':'保存配置'}}</button></div></form><template v-else><dl class="config-grid"><div><dt>评价月份</dt><dd>{{detail.cycle.month}}</dd></div><div><dt>规则版本</dt><dd>评分规则 V{{detail.cycle.rule_version??'—'}} · 冻结版本</dd></div><div><dt>评价开始</dt><dd>{{dateTime(detail.cycle.open_at)}}</dd></div><div><dt>自评截止</dt><dd>{{detail.cycle.self_close_at?dateTime(detail.cycle.self_close_at):'未设置（自评与他评同窗口）'}}</dd></div><div><dt>他评截止</dt><dd>{{dateTime(detail.cycle.close_at)}}</dd></div><div><dt>结果计划发布时间</dt><dd>{{dateTime(detail.cycle.publish_at)}}</dd></div><div><dt>配置版本</dt><dd>V{{detail.cycle.row_version}}</dd></div></dl><p class="hint">结果计划发布时间不代表自动公开成绩，仍需按现有流程确认并手动发布。</p><div v-if="['DRAFT','PENDING_OPEN'].includes(detail.cycle.status)" class="snapshot-note" role="status"><b>启动月评前检查</b><p v-if="allocationState==='checking'">正在检查已保存的评价关系…</p><p v-else-if="allocationState==='ready'">分配方案已保存且仍有效，可以进行启动前确认。系统还会检查周期时间和开期条件。</p><p v-else-if="allocationState==='missing'">尚无有效分配方案，或名单、人工关系已变化。请先重新预览并保存方案。</p><p v-else>当前账号无法检查分配方案，请联系有本周期分配权限的管理员。</p><RouterLink v-if="allocationState==='missing'" :to="{path:monthlyPath('relations'),query:{cycleId:detail.cycle.id}}" @click="dialog?.close()">前往评价分配 →</RouterLink></div><div class="detail-actions"><button v-if="rows.find(c=>c.id===detail?.cycle.id)?.can_manage && auth.hasCapability('cycle.manage')" class="btn" :disabled="busy" @click="remindMe">催办推送到我飞书</button><button v-if="rows.find(c=>c.id===detail?.cycle.id)?.can_manage && auth.hasCapability('assignment.manage') && ['DRAFT','PENDING_OPEN'].includes(detail.cycle.status)" class="btn btn-primary" :disabled="busy || allocationState!=='ready'" @click="preparePublish">发布月评</button><button v-if="detail.permissions.canEdit" class="btn btn-primary" :disabled="busy" @click="startEdit">编辑草稿配置</button><button v-if="detail.permissions.canArchive" class="btn" :disabled="busy" @click="confirmAction('archive')">归档周期</button><button v-if="detail.permissions.canPause" class="btn" :disabled="busy" @click="confirmAction('pause')">暂停月评</button><button v-if="detail.permissions.canResume" class="btn btn-primary" :disabled="busy" @click="confirmAction('resume')">恢复月评</button><button v-if="detail.permissions.canCancel" class="btn danger" :disabled="busy" @click="confirmAction('cancel')">紧急撤销月评</button><button v-if="detail.permissions.canRestore" class="btn btn-primary" :disabled="busy" @click="confirmAction('restore')">重启为草稿</button><button v-if="detail.permissions.canDelete" class="btn danger" :disabled="busy" @click="confirmAction('delete')">{{detail.cycle.status==='CANCELLED'?'删除已撤销周期':'删除草稿'}}</button></div></template></template>
   <template v-else-if="panel==='participants'"><div class="roster-head"><p class="hint">有效参评 {{detail.participants.filter(p=>p.eligibility==='ELIGIBLE').length}} 人 · 当前可见 {{detail.participants.length}} 人</p><button v-if="detail.permissions.canRefresh" class="btn" :disabled="busy" @click="confirmAction('refresh')">刷新参评快照</button></div><div class="table-wrap roster"><table><thead><tr><th>成员姓名</th><th>周期部门</th><th>周期角色</th><th>参评资格</th></tr></thead><tbody><tr v-for="p in detail.participants" :key="p.user_id"><td>{{p.display_name}}</td><td>{{p.department_name??'未分配'}}</td><td>{{p.role_snapshot==='HEAD'?'部长':p.role_snapshot==='MEMBER'?'成员':p.role_snapshot}}</td><td>{{p.eligibility==='ELIGIBLE'?'有效参评':'已排除'}}<small v-if="p.exclusion_reason">{{p.exclusion_reason}}</small></td></tr></tbody></table><p v-if="!detail.participants.length" class="empty">本周期暂无可见的参评快照</p></div><p class="hint">参评名单与评价关系分别管理；名单生成不代表评价任务已经分配。</p></template>
   <template v-else><ol class="state-log"><li v-for="(log,i) in detail.stateLog" :key="i"><b>{{cycleStatus({status:log.to_status})}}</b><span>{{dateTime(log.created_at)}}</span><p>{{log.reason}} · {{log.actor_name || '系统'}}</p></li></ol><p v-if="!detail.stateLog.length" class="empty">暂无阶段变更记录</p><RouterLink v-if="auth.hasCapability('result.read_published')&&['PUBLISHED','ARCHIVED','PARTIALLY_PUBLISHED'].includes(detail.cycle.status)" class="btn" :to="{path:'/management/archives',query:{tab:'scores',cycleId:detail.cycle.id}}">查看历史发布结果</RouterLink></template>
  </template></dialog>
  <dialog ref="progressDialog" class="cycle-dialog progress-dialog" aria-labelledby="progress-title" @close="progressRequest?.abort()"><div class="dialog-head"><h2 id="progress-title">{{progressKind}}详情</h2><button class="close" aria-label="关闭" @click="progressDialog?.close()">×</button></div><p class="hint">{{current?.title}} · 按周期内成员所属部门统计<span v-if="progressKind==='他评完成'">，他评任务按被评价人归集</span></p><div class="filters"><input v-model="progressSearch" aria-label="搜索成员" placeholder="搜索成员姓名"/><select v-model="progressDepartment" aria-label="筛选部门"><option value="">全部部门</option><option v-for="d in progressDepartments" :key="d">{{d}}</option></select></div><p v-if="progressLoading" role="status">正在加载进度…</p><p v-else-if="progressError" class="error" role="alert">{{progressError}} <button class="btn" @click="progressDialog?.close();openProgress(progressKind)">重试</button></p><template v-else><section v-for="g in progressGroups" :key="g.name" class="progress-group"><h3>{{g.name}} · {{g.items.length}} 人 <span v-if="progressKind==='材料提交'">（有效材料 {{g.items.reduce((n,r)=>n+r.materials,0)}} 份）</span><span v-if="progressKind==='自评完成'">（已完成 {{g.items.reduce((n,r)=>n+r.self_submitted,0)}} 人）</span><span v-if="progressKind==='他评完成'">（已完成 {{g.items.reduce((n,r)=>n+r.peer_submitted,0)}} / {{g.items.reduce((n,r)=>n+r.peer_expected,0)}} 项）</span></h3><table><thead><tr><th>成员</th><th>部门</th><th>{{progressKind==='参评人数'?'参评状态':progressKind==='他评完成'?'他评任务进度':'完成情况'}}</th></tr></thead><tbody><tr v-for="r in g.items" :key="r.user_id"><td>{{r.display_name}}</td><td>{{r.department_name||'未分配'}}</td><td v-if="progressKind==='参评人数'">有效参评</td><td v-else-if="progressKind==='材料提交'">{{r.materials ? '已提交（'+r.materials+' 份有效材料）':'未提交有效材料'}} <button v-if="r.materials" class="text-button" @click="openMemberDetails(r)">查看材料</button></td><td v-else-if="progressKind==='自评完成'">{{r.self_submitted?'已完成':'未完成'}}</td><td v-else>已完成 {{r.peer_submitted}} / {{r.peer_expected}} 项，未完成 {{Math.max(0,r.peer_expected-r.peer_submitted)}} 项 <button class="text-button" @click="openMemberDetails(r)">查看任务</button></td></tr></tbody></table></section><p v-if="!progressGroups.length" class="empty">暂无符合条件的成员</p><p v-if="progressKind==='材料提交'" class="hint">材料文件需通过现有材料查看入口及权限访问。</p></template></dialog>
  <dialog ref="extraDialog" class="cycle-dialog progress-dialog" aria-labelledby="extra-title"><div class="dialog-head"><h2 id="extra-title">{{extraTitle}}</h2><button class="close" aria-label="关闭" @click="extraDialog?.close()">×</button></div><p v-if="extraLoading" role="status">正在加载…</p><p v-else-if="extraError" class="error" role="alert">{{extraError}}</p><template v-else-if="progressKind==='材料提交'"><ul v-if="materialRows.length"><li v-for="m in materialRows" :key="m.id">{{m.name}} <a v-for="v in m.versions" :key="v.id" :href="`/api/v1/cycles/${selectedId}/participants/${extraMember?.user_id}/materials/${v.id}/file`" target="_blank" rel="noopener">预览 {{v.fileName}}</a></li></ul><p v-else class="empty">暂无可预览材料</p></template><template v-else><p class="hint">仅显示评价双方均在授权范围内的任务；不展示评分内容。任务数量可能少于进度汇总。</p><div class="detail-tabs"><button :class="{active:taskDirection==='outgoing'}" @click="taskDirection='outgoing'">作为评价人</button><button :class="{active:taskDirection==='incoming'}" @click="taskDirection='incoming'">作为被评价人</button></div><p class="hint">授权范围内：共 {{memberTasks.length}} 项，已完成 {{memberTasks.filter(t=>t.completed).length}} 项，未完成 {{memberTasks.filter(t=>!t.completed).length}} 项。</p><table><thead><tr><th>评价人</th><th>被评价人</th><th>任务状态</th></tr></thead><tbody><tr v-for="t in memberTasks" :key="t.id"><td>{{t.reviewer_name}}（{{t.reviewer_department||'未分配'}}）</td><td>{{t.target_name}}（{{t.target_department||'未分配'}}）</td><td>{{t.completed?'已完成':'未完成'}}</td></tr></tbody></table><p v-if="!memberTasks.length" class="empty">授权范围内暂无任务</p></template></dialog>
  <dialog ref="publishDialog" class="cycle-dialog action-dialog" aria-labelledby="publish-title" @cancel="busy&&$event.preventDefault()"><template v-if="detail"><h2 id="publish-title">发布月评</h2><p>{{detail.cycle.title}}</p><p>评价时间：{{dateTime(detail.cycle.open_at)}} — {{dateTime(detail.cycle.close_at)}}</p><p>参评人数：{{rows.find(c=>c.id===detail?.cycle.id)?.participants ?? '—'}}</p><p class="hint">确认后将锁定评价关系；周期进入评价中后，个人端可上传材料。月评结果需要另行发布。</p><p v-if="busy" role="status">正在处理…</p><template v-if="publishPreview"><p v-if="publishPreview.feasible">评价关系预检通过，共 {{publishPreview.edge_count}} 条关系。</p><template v-else><p class="error" role="alert">评价关系预检未通过，请前往评价分配处理：</p><ul class="error" style="margin:6px 0 10px;padding-left:20px"><li v-for="s in publishPreview.shortfalls" :key="s.targetId">{{s.targetName??'参评成员'}}（{{s.department_name??'部门未知'}}）目前可获得 {{s.indegree}} 份他评，至少需要 {{s.minIndegree}} 份，还缺 {{s.missing}} 份。原因可能：{{shortfallReasons[s.reason]??shortfallReasons.OTHER}}</li></ul><p v-for="reason in publishPreview.shortfalls?.length?[]:publishPreview.diagnostics" :key="reason" class="error">{{describeDiagnostic(reason)}}</p><p v-if="shortfallHint" class="hint">{{shortfallHint}}</p></template></template><p v-if="publishError" class="error" role="alert">{{publishError}}</p><RouterLink v-if="publishError || (publishPreview && !publishPreview.feasible)" :to="{path:monthlyPath('relations'),query:{cycleId:detail.cycle.id}}">前往评价分配</RouterLink><div class="dialog-footer"><button class="btn" :disabled="busy" @click="publishDialog?.close()">取消</button><button class="btn btn-primary" :disabled="busy || !publishPreview?.feasible" @click="publishCycle">确认发布</button></div></template></dialog>
  <dialog ref="actionDialog" class="cycle-dialog action-dialog" aria-labelledby="cycle-action-title" @cancel="busy&&$event.preventDefault()"><h2 id="cycle-action-title">{{({delete:(detail?.cycle.status==='CANCELLED'?'删除已撤销周期':'删除草稿周期'),restore:'重启为草稿',archive:'归档周期',cancel:'紧急撤销月评',pause:'暂停月评',resume:'恢复月评',refresh:'刷新参评快照'} as Record<string,string>)[action]}}</h2><p class="hint">{{({delete:(detail?.cycle.status==='CANCELLED'?'将删除该已撤销周期，以及它名下的评价记录、月度材料、结果与阶段记录，不可恢复；删除后该月份可以重新创建。':'仅无正式业务关联的草稿可以删除，此操作不可恢复。'),restore:'将清空本期的评价记录、月度材料与结果数据，保留参评名单和阶段记录，然后把周期退回草稿状态，可重新配置并发起。',archive:'归档后只读，正式结果与历史记录继续保留。',cancel:'确认紧急撤销？撤销后不能继续评价，已有材料和评价记录保留；正式发布结果不可撤销。',pause:'暂停后停止材料和评价提交，截止时间不会自动延长。',resume:'恢复后仍按原有截止时间执行；如果已经截止，将不能继续提交。',refresh:'按当前有效组织名单重新生成草稿参评快照，已有分配预检将失效。'} as Record<string,string>)[action]}}</p><div v-if="action==='archive'"><p v-if="busy">正在检查归档条件…</p><ul v-if="archiveCheck"><li v-for="check in archiveCheck.checks" :key="check.key">{{check.ok ? '✓' : '✕'}} {{check.message}} <RouterLink v-if="!check.ok && check.path" :to="{path:check.path,query:{cycleId:detail?.cycle.id}}" @click="actionDialog?.close();dialog?.close()">前往处理</RouterLink></li></ul></div><label v-if="['cancel','pause','resume'].includes(action)" class="reason-label">操作原因 <em>*</em><textarea v-model="actionReason" maxlength="500" rows="4"/></label><p v-if="actionError" class="error" role="alert">{{actionError}}</p><div class="dialog-footer"><button class="btn" :disabled="busy" @click="actionDialog?.close()">取消</button><button class="btn" :class="action==='delete'||action==='cancel'?'danger':'btn-primary'" :disabled="busy || (action==='archive' && !archiveCheck?.eligible)" @click="execute">{{busy?'处理中…':'确认操作'}}</button></div></dialog>
 </div>
